function donut(c,n){const C=238.76,cs={R:"#d63a3a",O:"#e07a1f",Y:"#c9a400",G:"#2e9d5b"};let o=0;return`<svg viewBox="0 0 100 100" width="120" height="120">${["R","O","Y","G"].map(z=>{const l=c[z]/n*C,x=`<circle cx="50" cy="50" r="38" fill="none" stroke="${cs[z]}" stroke-width="16" stroke-dasharray="${l} ${C-l}" stroke-dashoffset="${-o}" transform="rotate(-90 50 50)"/>`;o+=l;return x}).join("")}<text x="50" y="55" text-anchor="middle" font-size="16" font-weight="700" fill="var(--tx)">${n}곳</text></svg>`}
