function rqGo(i){const e=document.getElementById("rq-s"+i);if(e)e.scrollIntoView({behavior:"smooth",block:"start"});document.querySelectorAll("#ig .rqtb button,#ig .rfst button").forEach(b=>b.classList.toggle("on",+b.dataset.i==i))}
let rqT=0;function rqSpy(){const tb=document.querySelector("#ig .rqtb,#ig .rfst");if(!tb)return;const sb=document.querySelector("#v9 .lxsb"),sp=parseFloat(getComputedStyle(document.documentElement).scrollPaddingTop)||0,off=Math.max((sb?sb.getBoundingClientRect().bottom:0),sp)+40;let cur=1;for(let i=1;i<=6;i++){const e=document.getElementById("rq-s"+i);if(e&&e.getBoundingClientRect().top<=off)cur=i}if(cur>5)cur=5;tb.querySelectorAll("button").forEach(b=>b.classList.toggle("on",+b.dataset.i==cur))}
window.addEventListener("scroll",()=>{if(rqT)return;rqT=setTimeout(()=>{rqT=0;rqSpy()},80)},{passive:true});
function rqClone(ig){const c=ig.cloneNode(true);c.querySelectorAll(".rq-nx").forEach(e=>e.remove());return c}
async function rqPdf(){const ig=document.getElementById("ig");if(!ig){tt("보고서 화면에서 실행하세요");return}
let box;try{tt("PDF를 만드는 중입니다…");await ldp();await ldj();
const c=rqClone(ig);c.style.setProperty("--q","1px");c.style.setProperty("--f","1px");c.style.setProperty("--w","1px");c.style.cssText+=";width:852px;position:relative;background:#f1f6fd;padding:0";
box=document.createElement("div");box.style.cssText="position:fixed;left:-10000px;top:0;width:852px";const w=document.createElement("div");w.id="v9";w.append(c);box.append(w);document.body.append(box);
await new Promise(r=>setTimeout(r,200));
const secs=[...c.querySelectorAll(".rq-sec")].map(e=>({y:e.offsetTop,h:e.offsetHeight})),SC=2,cv=await html2canvas(c,{scale:SC,backgroundColor:"#f1f6fd",windowWidth:852,scrollX:0,scrollY:0});
const H=Math.floor(852*297/210)-24,pages=[];let st=0,en=0;secs.forEach((s,i)=>{const b=s.y+s.h;if(en&&b-st>H){pages.push([st,en]);st=s.y-14}en=b;if(i==0)st=Math.max(0,s.y-14)});pages.push([st,en+14]);
const J=window.jspdf.jsPDF,pdf=new J({unit:"mm",format:"a4"}),W=210;
pages.forEach((p,i)=>{const y0=Math.max(0,Math.round(p[0]*SC)),h=Math.min(cv.height-y0,Math.round((p[1]-p[0])*SC)),c2=document.createElement("canvas");c2.width=cv.width;c2.height=h;const g=c2.getContext("2d");g.fillStyle="#f1f6fd";g.fillRect(0,0,c2.width,c2.height);g.drawImage(cv,0,y0,cv.width,h,0,0,cv.width,h);if(i)pdf.addPage();pdf.addImage(c2.toDataURL("image/jpeg",.9),"JPEG",0,0,W,h*W/cv.width,undefined,"FAST")});
const mt=rptMeta(),nm="LCC_종합분석보고서_"+mt.id+".pdf";dl(pdf.output("blob"),nm);tt("PDF를 저장했습니다<br><small>"+nm+"</small>");rnBump()}
catch(x){tt("PDF 생성에 실패했습니다<br>온라인 연결을 확인하거나 HTML로 저장하세요")}finally{if(box)box.remove()}}
