function donutS(v,tot){const C=2*Math.PI*106;let o=0,txt="";const seg=v.map((x,i)=>{const l=tot>0?x/tot*C:0,s=`<circle cx="142" cy="142" r="106" fill="none" stroke="${DC[i]}" stroke-width="72" stroke-dasharray="${l} ${C-l}" stroke-dashoffset="${-o}" transform="rotate(-90 142 142)"/>`;const mid=(o+l/2)/C*2*Math.PI-Math.PI/2;if(tot>0&&x/tot>=.07)txt+=`<text x="${142+106*Math.cos(mid)}" y="${142+106*Math.sin(mid)+8}" text-anchor="middle" font-size="24" font-weight="700" fill="#fff">${Math.round(x/tot*100)}%</text>`;o+=l;return s}).join("");
return`<svg viewBox="0 0 284 284" class="ldpie">${seg}${txt}<circle cx="142" cy="142" r="70" fill="#fff"/><text x="142" y="124" text-anchor="middle" font-size="22" fill="#4a5b7c">Total</text><text x="142" y="158" text-anchor="middle" font-size="${F(tot/1000).length>7?26:32}" font-weight="800" fill="#10264f">${F(tot/1000)}</text><text x="142" y="184" text-anchor="middle" font-size="19" fill="#6b7b95">백만원</text></svg>`}
function dHero(){const urg=dRows().filter(r=>r.B.z=="R"||r.B.z=="O").length;return`<div class="ldh" style="background-image:url(data:image/jpeg;base64,)"><h1>LCC</h1><div class="lds">Life Cycle Cost</div><i class="ldu"></i><p>설비의 생애주기 전체를<br>데이터로 관리합니다.</p>
<button class="ldbell" onclick="tt('긴급 보수 대상 ${urg}곳 (R·O 등급)')" aria-label="알림">${MI('<path d="M6 16V11a6 6 0 0 1 12 0v5l1.5 2h-15z"/><path d="M10 21h4"/>')}${urg?"<i></i>":""}</button><button class="ldgear" onclick="openSettings()" aria-label="설정">${MI('<circle cx="12" cy="12" r="3"/><path d="M12 2.5v3M12 18.5v3M2.5 12h3M18.5 12h3M5.3 5.3l2.1 2.1M16.6 16.6l2.1 2.1M5.3 18.7l2.1-2.1M16.6 7.4l2.1-2.1"/>')}</button></div>`}
const LXC={ef:3.0,den:1.4};/* CO₂ 환산 가정: 도료 1kg당 3.0kgCO₂e, 비중 1.4kg/L */
function lxCo2(m,a){const l=m.sc.cs.reduce((x,y)=>x+y.acv,0)*a.ar,n=Math.ceil(RS.hz/Math.max(1,m.c));return l*LXC.den*LXC.ef*n/Math.max(1,RS.hz)/1000}
