function lxStrip(){return`<div class="lxt"><div class="lxtr">${TABS.map((t,i)=>`<button type="button" class="${i==RS.tab?"on":""}" onclick="LCCX.tab(${i})">${MI(TI[i])}<span>${t[0]}</span></button>`).join("")}</div><button type="button" class="lxtn" onclick="this.previousElementSibling.scrollBy({left:220,behavior:'smooth'})" aria-label="다음 탭">${MI(lxCh)}</button></div>`}
function lxChart(rows,VH){VH=Math.max(232,Math.round(VH||232));const N=Math.max(2,Math.min(RS.dr>0?RS.dr:RS.hz,RS.hz)+1),y0=new Date().getFullYear();
const S=k=>{const o=[];for(let y=0;y<N;y++)o.push(rows.reduce((s,r)=>s+(r.m[k].cu[y]||0),0)/1000);return o},A=S(0),B=S(2);
const mx=Math.max(1,...A,...B),p=Math.pow(10,Math.floor(Math.log10(mx/4))),st=([1,2,2.5,5,10].map(s=>s*p).find(s=>s*4>=mx)||p*10),top=st*4;
const X=i=>64+i*(282/(N-1)),Y=v=>(VH-36)-v/top*(VH-62);
const grid=[0,1,2,3,4].map(i=>`<line x1="64" x2="346" y1="${Y(st*i)}" y2="${Y(st*i)}" stroke="#e3eaf6"/><text x="58" y="${Y(st*i)+7}" text-anchor="end" font-size="20" fill="#6b7b95">${+(st*i).toFixed(1)}</text>`).join("");
const nl=Math.min(N,4),xs=[...new Set(Array.from({length:nl},(_,i)=>Math.round(i*(N-1)/(nl-1))))].map(i=>`<text x="${i==N-1?X(i)+10:X(i)}" y="${VH-9}" text-anchor="${i==N-1?"end":"middle"}" font-size="20" fill="#6b7b95">${y0+i}</text>`).join("");
const pl=s=>s.map((v,i)=>`${X(i)},${Y(v)}`).join(" "),area=`${X(0)},${VH-36} ${pl(A)} ${X(N-1)},${VH-36}`;
const dots=(s,c)=>N<=11?s.map((v,i)=>`<circle cx="${X(i)}" cy="${Y(v)}" r="4" fill="${c}"/>`).join(""):"";
return`<svg viewBox="0 0 360 ${VH}" class="lxsvg" role="img" aria-label="누적 비용 추이">${grid}${xs}<polygon points="${area}" fill="#2a7bf0" opacity=".08"/><polyline points="${pl(A)}" fill="none" stroke="#1d62dc" stroke-width="2.5" stroke-linejoin="round"/><polyline points="${pl(B)}" fill="none" stroke="#12a366" stroke-width="2.5" stroke-linejoin="round"/>${dots(A,"#1d62dc")}${dots(B,"#12a366")}</svg>`}

