const es=rows.map(r=>r.m[0].e),mn=Math.round(Math.min(...es)),mx=Math.round(Math.max(...es)),life=mn==mx?mn+"년":mn+"~"+mx+"년";
const comp=[0,0,0,0,0];rows.forEach(r=>{const m=r.m[0],s=r.a.sp.cur,mat=m.sc.mat*r.a.ar/1000,lab=s.lab*r.a.ar/1000;for(let y=0,k=0;y<RS.hz;y+=m.c,k++){const f=1+RS.esc/100*k;if(k==0){comp[0]+=mat;comp[1]+=lab}else{comp[2]+=mat;comp[3]+=lab}comp[4]+=(mat+lab)*(f-1)}});const ct=comp.reduce((x,y)=>x+y,0);
