const urg2=rows.filter(r=>r.B.z=="R"||r.B.z=="O").length,co=rows.reduce((s,r)=>[s[0]+lxCo2(r.m[0],r.a),s[1]+lxCo2(r.m[2],r.a)],[0,0]),cs=co[0]-co[1],cp=co[0]>0?cs/co[0]*100:0,d0=(T0-T2)/(T0||1)*100,d2=(I0-I2)/(I0||1)*100;
const KL=Object.assign({},KI,{leaf:'<path d="M20 4C10 4 4.5 9 4.5 15.5c0 2 .8 3.5.8 3.5s1.5.7 3.5.7C15.3 19.7 20 14 20 4z"/><path d="M5.3 19C8 14 11 11 15 8.5"/>'});
