const rg=RS.dr>0?RS.dr:0,rgs=`<label class="lxpill lxrg"><span>${rg?"처음 "+rg+"년":"전체 "+RS.hz+"년"}</span>${MI('<path d="M6 9l6 6 6-6"/>')}<select aria-label="기간" onchange="LCCX.dr(this.value)"><option value="5"${rg==5?" selected":""}>처음 5년</option><option value="10"${rg==10?" selected":""}>처음 10년</option><option value="0"${rg==0?" selected":""}>전체 ${RS.hz}년</option></select></label>`;
